function PiMark({ compact = false }: { compact?: boolean }) {
  return (
    <div className={`flex items-center gap-3 ${compact ? "gap-2" : ""}`}>
      <div className="relative flex size-10 items-center justify-center rounded-xl bg-[#a7e1ff] text-[#07101a] shadow-[0_0_28px_rgba(105,201,255,.28)]">
        <span className="font-[Space_Grotesk] text-[25px] font-bold leading-none">π</span>
        <span className="absolute -right-1 -top-1 size-2 rounded-full bg-[#71f6af] ring-2 ring-[#080d15]" />
      </div>
      {!compact && <div><div className="font-[Space_Grotesk] text-[18px] font-bold tracking-[.18em] text-white">PIE</div><div className="text-[10px] tracking-[.16em] text-slate-500">PRIVATE CIRCLE</div></div>}
    </div>
  );
}

function PiAvatar({ name, size = "md", online = false, tone = "from-cyan-300 to-blue-500" }: { name?: string | null; size?: "sm" | "md" | "lg"; online?: boolean; tone?: string }) {
  const sizeClass = size === "lg" ? "size-14 text-xl" : size === "sm" ? "size-8 text-xs" : "size-10 text-sm";
  return <div className={`relative flex ${sizeClass} shrink-0 items-center justify-center rounded-xl bg-gradient-to-br ${tone} font-[Space_Grotesk] font-bold text-[#07101a] shadow-inner`}><span>π</span>{online && <span className="absolute -bottom-0.5 -right-0.5 size-2.5 rounded-full bg-[#71f6af] ring-2 ring-[#0b111b]" />}</div>;
}

function formatRelative(value: Date | string | null | undefined) {
  if (!value) return "just now";
  const date = new Date(value);
  const diff = Date.now() - date.getTime();
  if (diff < 60_000) return "just now";
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`;
  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`;
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function formatPlanDate(value: Date | string) {
  return new Date(value).toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" });
}

function GlassCard({ children, className = "", onClick }: { children: ReactNode; className?: string; onClick?: () => void }) {
  return <div onClick={onClick} className={`glass rounded-2xl ${onClick ? "cursor-pointer transition hover:-translate-y-0.5 hover:border-[rgba(160,202,235,.24)]" : ""} ${className}`}>{children}</div>;
}

function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: ReactNode }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div>{eyebrow && <div className="mb-1 text-[10px] font-semibold uppercase tracking-[.2em] text-[#69c9ff]">{eyebrow}</div>}<h2 className="font-[Space_Grotesk] text-xl font-semibold tracking-[-.02em] text-white">{title}</h2></div>{action}</div>;
}

